const APP_META = Object.fromEntries(
  APP_CONFIG.map(({ id, icon, labelKey, descriptionKey, color, category, suite, interest }) => [
    id,
    { icon, labelKey, descriptionKey, color, category, suite, interest },
  ])
);

const HOME_HIDDEN = new Set(APP_CONFIG.filter((a) => a.homeHidden).map((a) => a.id));

const VISIBLE_CONFIG = APP_CONFIG.filter((a) => a.enabled && !a.homeHidden);

const CATEGORY_ORDER = ['All', 'Live', 'School', 'Explore', 'Create', 'Inspect', 'Connect', 'Content', 'Fun', 'Lab'];

const SUITE_ORDER = ['AI Lab', 'Data Studio', 'Life Dashboard', 'Learning Hub', 'Game Room', 'Entertainment'];
const ALL_SUITES = SUITE_ORDER.filter((s) =>
  VISIBLE_CONFIG.some((a) => APP_META[a.id]?.suite === s),
);

function greeting(locale: Locale): string {
  const h = new Date().getHours();
  const key = h < 12 ? 'greeting.morning' : h < 19 ? 'greeting.afternoon' : 'greeting.evening';
  return t(key, locale);
}

