// ─── Component ────────────────────────────────────────────────────────────────

interface HomeScreenProps {
  apps: AppDefinition[];
  recentAppIds: string[];
  pinnedAppIds: string[];
  onTogglePin: (appId: string) => void;
  onMovePinned: (appId: string, direction: -1 | 1) => void;
  onSelect: (app: AppDefinition) => void;
  user?: { name?: string; email: string; avatarUrl?: string } | null;
  onSignOut?: () => void;
  /** Opens the shared ProfileModal (preferences). Owned by shell App.tsx so one
   *  modal instance is reused across home + remote apps. */
  onPreferences?: () => void;
}

export function HomeScreen({ apps: rawApps, recentAppIds, pinnedAppIds, onTogglePin, onMovePinned, onSelect, user, onSignOut, onPreferences }: HomeScreenProps) {
  const [profile] = useProfile();
  // Filter by interests only — age mode does NOT hide apps. Apps that need to
  // respect age mode (e.g. Movies, MoviesWidget) adjust their own content
  // internally instead of disappearing from the home screen.
  const apps = useMemo(() => rawApps.filter((a) => {
    if (HOME_HIDDEN.has(a.id)) return false;
    const meta = APP_META[a.id];
    if (!meta) return true;
    if (hasInterests(profile) && meta.interest && !profile.interests.includes(meta.interest)) return false;
    return true;
  }), [rawApps, profile]);
  const [sidebarView, setSidebarView]       = useState<'home' | 'apps'>('home');
  const [activeCategory, setActiveCategory] = useState('All');
  const [activeSuite, setActiveSuite]       = useState<string | null>(null);
  const [search, setSearch]                 = useState('');

  const goHome = useCallback(() => {
    setSidebarView('home');
    setActiveCategory('All');
    setActiveSuite(null);
    setSearch('');
  }, []);

  const selectSuite = useCallback((s: string) => {
    setSidebarView('apps');
    setActiveSuite(s);
    setActiveCategory('All');
  }, []);

  const [suitesCollapsed, setSuitesCollapsed] = useState(true);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      const suiteVal = await getSetting('shell:suites-collapsed');
      if (cancelled) return;
      if (suiteVal !== null) setSuitesCollapsed(suiteVal === 'true');
    })();
    return () => { cancelled = true; };
  }, []);

  const toggleSuites = useCallback(() => {
    setSuitesCollapsed((prev) => {
      const next = !prev;
      putSetting('shell:suites-collapsed', String(next));
      return next;
    });
  }, []);
  const [locale, setLocale]                 = useLocale();
  const tShell = useMemo(() => createT(locale, SHELL_KEYS), [locale]);
  const searchInputRef = useRef<HTMLInputElement>(null);
  const widgetAppMeta = useMemo(() => {
    const meta: Record<string, { icon: string; label: string; description: string; color: string }> = {};
    for (const app of apps) {
      const m = APP_META[app.id];
      if (m) meta[app.id] = {
        icon: m.icon,
        label: tShell(m.labelKey),
        description: tShell(m.descriptionKey),
        color: m.color,
      };
    }
    return meta;
  }, [apps, tShell]);

  const filtered = useMemo(() => {
    const q = search.toLowerCase();
    return apps.filter((app) => {
      const meta = APP_META[app.id];
      const matchesCategory = activeCategory === 'All' || meta?.category === activeCategory;
      const matchesSuite = !activeSuite || meta?.suite === activeSuite;
      const description = meta ? tShell(meta.descriptionKey) : '';
      const matchesSearch = !q || app.label.toLowerCase().includes(q) || description.toLowerCase().includes(q);
      const isPinned = !search && activeCategory === 'All' && !activeSuite && pinnedAppIds.includes(app.id);
      return matchesCategory && matchesSuite && matchesSearch && !isPinned;
    });
  }, [apps, activeCategory, activeSuite, search, pinnedAppIds, tShell]);

  const grouped = useMemo((): { type: 'suite' | 'category'; groups: Record<string, AppDefinition[]> } | null => {
    if (search) return null;
    if (activeCategory !== 'All') return null;

    if (activeSuite) {
      // Within a suite filter, group by category
      const groups: Record<string, AppDefinition[]> = {};
      for (const app of filtered) {
        const cat = APP_META[app.id]?.category ?? 'Other';
        if (!groups[cat]) groups[cat] = [];
        groups[cat].push(app);
      }
      return { type: 'category', groups };
    }

    // "All" view: group by suite
    const groups: Record<string, AppDefinition[]> = {};
    for (const app of filtered) {
      const s = APP_META[app.id]?.suite ?? 'Other';
      if (!groups[s]) groups[s] = [];
      groups[s].push(app);
    }
    return { type: 'suite', groups };
  }, [filtered, activeCategory, activeSuite, search]);

  const suiteCounts = useMemo(() => {
    const counts: Record<string, number> = {};
    for (const app of apps) {
      const s = APP_META[app.id]?.suite;
      if (s) counts[s] = (counts[s] ?? 0) + 1;
    }
    // +1 for the Dev Tools gateway card injected into AI Lab
    counts['AI Lab'] = (counts['AI Lab'] ?? 0) + 1;
    return counts;
  }, [apps]);

  const pinnedApps = useMemo(
    () => pinnedAppIds.flatMap((id) => apps.filter((a) => a.id === id)),
    [pinnedAppIds, apps],
  );
  const recentApps = useMemo(
    () => recentAppIds
      .filter((id) => !pinnedAppIds.includes(id))
      .flatMap((id) => apps.filter((a) => a.id === id))
      .slice(0, 6),
    [recentAppIds, pinnedAppIds, apps],
  );

  let cardIndex = 0;

  const renderCard = (app: AppDefinition, idx: number, pinCtx?: { pinIdx: number; total: number }) => {
    const meta = APP_META[app.id];
    const isPinned = pinnedAppIds.includes(app.id);
    const desc = meta ? tShell(meta.descriptionKey) : '';
    const displayLabel = app.label; // already translated by App.tsx
    const color = meta?.color ?? theme.colors.accent;
    const icon = meta?.icon ?? '🔲';
    return (
      <Card
        key={app.id}
        accentColor={color}
        index={idx}
        pinned={isPinned}
        onClick={() => onSelect(app)}
      >
        {pinCtx && pinCtx.total > 1 && (
          <PinControls className="pin-controls">
            {pinCtx.pinIdx > 0 && (
              <PinControlBtn
                title={locale === 'pt' ? 'Mover para a esquerda' : 'Move left'}
                onClick={(e) => { e.stopPropagation(); onMovePinned(app.id, -1); }}
              >
                <ChevronLeft size={13} />
              </PinControlBtn>
            )}
            {pinCtx.pinIdx < pinCtx.total - 1 && (
              <PinControlBtn
                title={locale === 'pt' ? 'Mover para a direita' : 'Move right'}
                onClick={(e) => { e.stopPropagation(); onMovePinned(app.id, 1); }}
              >
                <ChevronRight size={13} />
              </PinControlBtn>
            )}
          </PinControls>
        )}
        <PinBtn
          className="pin-btn"
          pinned={isPinned}
          role="button"
          title={isPinned ? 'Unpin' : 'Pin to top'}
          onClick={(e) => { e.stopPropagation(); onTogglePin(app.id); }}
        >
          <Pin size={16} fill={isPinned ? 'currentColor' : 'none'} />
        </PinBtn>
        <CardIconWrap className="card-icon" accentColor={color} style={{ background: `${color}18` }}>
          {icon}
        </CardIconWrap>
        <CardLabel>{displayLabel}</CardLabel>
        <CardDesc>{desc}</CardDesc>
        <CardFooter className="card-footer" accentColor={color}>{t('open', locale)} &rarr;</CardFooter>
      </Card>
    );
  };

  return (
    <>
      <Page>
        <TopBar>
          <TopBarLogo onClick={() => { window.location.hash = '#/home'; }} title="Home">
            <span>Atl</span><span className="logo-accent">antis</span>
          </TopBarLogo>
          <TopBarRight>
            <HeaderRight
              locale={locale}
              onLocaleChange={setLocale}
              onPreferences={onPreferences}
              user={user ? { name: user.name, email: user.email, avatarUrl: user.avatarUrl } : undefined}
              userMenuItems={user && onSignOut ? [
                { label: 'Settings', icon: <Settings size={14} />, onClick: () => { window.location.hash = '#/settings'; } },
                { label: 'Sign out', icon: <LogOut size={14} />, onClick: onSignOut, danger: true },
              ] : []}
              onSignIn={() => { window.location.hash = '#/home'; }}
            />
          </TopBarRight>
        </TopBar>
        <Body>
        <Sidebar>
          <SidebarItem
            active={sidebarView === 'home'}
            onClick={goHome}
          >
            <span style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
              <Home size={14} />
              {locale === 'pt' ? 'Início' : 'Home'}
            </span>
          </SidebarItem>
          <SidebarDivider />
          {ALL_SUITES.length > 0 && (
            <>
              <SidebarHeading onClick={toggleSuites}>
                {t('suites', locale)}
                <ChevronIcon collapsed={suitesCollapsed} />
              </SidebarHeading>
              <CollapsibleSection collapsed={suitesCollapsed}>
                <CollapsibleInner>
                  {ALL_SUITES.map((s) => (
                    <SidebarItem
                      key={s}
                      active={sidebarView === 'apps' && activeSuite === s}
                      onClick={() => selectSuite(s)}
                    >
                      <span style={{ flex: 1, textAlign: 'left' }}>{suiteLabel(s, locale)}</span>
                      <SidebarCount active={sidebarView === 'apps' && activeSuite === s}>{suiteCounts[s] ?? 0}</SidebarCount>
                    </SidebarItem>
                  ))}
                </CollapsibleInner>
              </CollapsibleSection>
              <SidebarDivider />
            </>
          )}
        </Sidebar>

        <Main>
          <Header>
            <Greeting>
              {greeting(locale)}{user?.name ? (
                <>, <span className="accent">{user.name.split(' ')[0]}</span></>
              ) : null}
            </Greeting>
            <Tagline>{t('tagline', locale)}</Tagline>
            <SearchWrap>
              <SearchInput
                ref={searchInputRef}
                placeholder={t('searchApps', locale)}
                value={search}
                onChange={(e) => {
                  setSearch(e.target.value);
                  if (e.target.value && sidebarView === 'home') setSidebarView('apps');
                }}
              />
              <SearchIcon><Search size={16} /></SearchIcon>
              <KbdHint>
                <kbd>⌘</kbd><kbd>K</kbd>
              </KbdHint>
            </SearchWrap>
          </Header>

          {sidebarView === 'home' && !search && (
            <WidgetGrid
              locale={locale}
              pinnedAppIds={pinnedAppIds}
              recentAppIds={recentAppIds}
              apps={apps}
              appMeta={widgetAppMeta}
              onSelectApp={onSelect}
              onTogglePin={onTogglePin}
            />
          )}

          {sidebarView === 'apps' && (
            <>
              {filtered.length === 0 && search && (
                <EmptyState>{t('noMatch', locale)} &ldquo;{search}&rdquo;</EmptyState>
              )}

              {!search && activeCategory === 'All' && !activeSuite && pinnedApps.length > 0 && (
                <div>
                  <SectionLabel>{t('pinned', locale)}</SectionLabel>
                  <Grid>
                    {pinnedApps.map((app, i) => renderCard(app, cardIndex++, { pinIdx: i, total: pinnedApps.length }))}
                  </Grid>
                </div>
              )}

              {!search && activeCategory === 'All' && !activeSuite && recentApps.length > 0 && (
                <div>
                  <SectionLabel>{t('recentlyUsed', locale)}</SectionLabel>
                  <Grid>
                    {recentApps.map((app) => renderCard(app, cardIndex++))}
                  </Grid>
                </div>
              )}

              {grouped ? (
                [...(grouped.type === 'suite' ? SUITE_ORDER : CATEGORY_ORDER.slice(1)), 'Other']
                  .filter((key) => grouped.groups[key]?.length > 0)
                  .map((key) => (
                    <div key={key}>
                      <SectionLabel>
                        {grouped.type === 'suite' ? suiteLabel(key, locale) : categoryLabel(key, locale)}
                      </SectionLabel>
                      <Grid>
                        {grouped.groups[key].map((app) => renderCard(app, cardIndex++))}
                        {((grouped.type === 'suite' && key === 'AI Lab') || (grouped.type === 'category' && key === 'Lab')) && (
                          <Card
                            accentColor="#facc15"
                            index={cardIndex++}
                            pinned={pinnedAppIds.includes('devtools')}
                            onClick={() => { window.location.hash = '#/playground'; }}
                          >
                            <PinBtn
                              className="pin-btn"
                              pinned={pinnedAppIds.includes('devtools')}
                              role="button"
                              title={pinnedAppIds.includes('devtools') ? 'Unpin' : 'Pin to top'}
                              onClick={(e) => { e.stopPropagation(); onTogglePin('devtools'); }}
                            >
                              <Pin size={16} fill={pinnedAppIds.includes('devtools') ? 'currentColor' : 'none'} />
                            </PinBtn>
                            <CardIconWrap className="card-icon" accentColor="#facc15" style={{ background: '#facc1518' }}>
                              🛠️
                            </CardIconWrap>
                            <CardLabel>{locale === 'pt' ? 'Dev Tools' : 'Dev Tools'}</CardLabel>
                            <CardDesc>{locale === 'pt' ? '11 ferramentas de desenvolvimento' : '11 developer tools'}</CardDesc>
                            <CardFooter className="card-footer" accentColor="#facc15">{t('open', locale)} &rarr;</CardFooter>
                          </Card>
                        )}
                      </Grid>
                    </div>
                  ))
              ) : (
                <Grid>
                  {filtered.map((app) => renderCard(app, cardIndex++))}
                  {activeCategory === 'Lab' && (
                    <Card
                      accentColor="#facc15"
                      index={cardIndex++}
                      pinned={pinnedAppIds.includes('devtools')}
                      onClick={() => { window.location.hash = '#/playground'; }}
                    >
                      <PinBtn
                        className="pin-btn"
                        pinned={pinnedAppIds.includes('devtools')}
                        role="button"
                        title={pinnedAppIds.includes('devtools') ? 'Unpin' : 'Pin to top'}
                        onClick={(e) => { e.stopPropagation(); onTogglePin('devtools'); }}
                      >
                        <Pin size={16} fill={pinnedAppIds.includes('devtools') ? 'currentColor' : 'none'} />
                      </PinBtn>
                      <CardIconWrap className="card-icon" accentColor="#facc15" style={{ background: '#facc1518' }}>
                        🛠️
                      </CardIconWrap>
                      <CardLabel>Dev Tools</CardLabel>
                      <CardDesc>{locale === 'pt' ? '11 ferramentas de desenvolvimento' : '11 developer tools'}</CardDesc>
                      <CardFooter className="card-footer" accentColor="#facc15">{t('open', locale)} &rarr;</CardFooter>
                    </Card>
                  )}
                </Grid>
              )}
            </>
          )}
        </Main>
        </Body>
      </Page>
    </>
  );
}
