// --- Key definitions ---

interface KeyDef {
  id: string;
  label: string;
  placeholder: string;
  help: string;
  linkUrl: string;
  linkLabel: string;
}

const API_KEYS: KeyDef[] = [
  {
    id: 'groq',
    label: 'Groq',
    placeholder: 'gsk_...',
    help: 'Used by Prompt Lab and Image Gen (enhance)',
    linkUrl: 'https://console.groq.com/keys',
    linkLabel: 'Get key',
  },
  {
    id: 'gemini',
    label: 'Google Gemini',
    placeholder: 'AIza...',
    help: 'Used by Prompt Lab',
    linkUrl: 'https://aistudio.google.com/apikey',
    linkLabel: 'Get key',
  },
];

const STORAGE_KEY = 'atlantis:api-keys';
const LEGACY_KEY = 'atlantis:promptlab:keys';

interface ApiKeys {
  groq: string;
  gemini: string;
}

const EMPTY: ApiKeys = { groq: '', gemini: '' };

function loadKeys(): ApiKeys {
  // Read from new location first, fall back to legacy promptlab key
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (raw) return { ...EMPTY, ...JSON.parse(raw) };
    const legacy = localStorage.getItem(LEGACY_KEY);
    if (legacy) return { ...EMPTY, ...JSON.parse(legacy) };
  } catch { /* ignore */ }
  return { ...EMPTY };
}

function persistKeys(keys: ApiKeys) {
  const json = JSON.stringify(keys);
  // Write to both locations for backward compat with Prompt Lab / Image Gen
  localStorage.setItem(STORAGE_KEY, json);
  localStorage.setItem(LEGACY_KEY, json);
  // Also persist to IndexedDB/Supabase for cloud sync
  putSetting(STORAGE_KEY, json);
}

interface SettingsPageProps {
  lang: string;
}

export function SettingsPage({ lang }: SettingsPageProps) {
  const [keys, setKeys] = useState<ApiKeys>(EMPTY);
  const [visible, setVisible] = useState<Record<string, boolean>>({});
  const [saved, setSaved] = useState(false);
  const [dirty, setDirty] = useState(false);

  useEffect(() => {
    // Load from localStorage first (instant), then check putSetting for cloud sync
    const local = loadKeys();
    setKeys(local);

    getSetting(STORAGE_KEY).then((cloud) => {
      if (cloud) {
        try {
          const parsed = { ...EMPTY, ...JSON.parse(cloud) };
          // Merge: prefer non-empty values
          const merged: ApiKeys = {
            groq: local.groq || parsed.groq,
            gemini: local.gemini || parsed.gemini,
          };
          setKeys(merged);
        } catch { /* ignore */ }
      }
    });
  }, []);

  const handleChange = useCallback((id: string, value: string) => {
    setKeys((prev) => ({ ...prev, [id]: value }));
    setDirty(true);
    setSaved(false);
  }, []);

  const handleClear = useCallback((id: string) => {
    setKeys((prev) => ({ ...prev, [id]: '' }));
    setDirty(true);
    setSaved(false);
  }, []);

  const handleSave = useCallback(() => {
    persistKeys(keys);
    setDirty(false);
    setSaved(true);
    setTimeout(() => setSaved(false), 2500);
  }, [keys]);

  const pt = lang === 'pt';

  return (
    <Page>
      <Container>
        <Header>
          <Title>{pt ? 'Definições' : 'Settings'}</Title>
          <Subtitle>
            {pt
              ? 'Gere as tuas chaves de API para os serviços de IA. As chaves são guardadas no teu browser e sincronizadas com a tua conta.'
              : 'Manage your API keys for AI services. Keys are stored in your browser and synced with your account.'}
          </Subtitle>
        </Header>

        <Section>
          <SectionTitle>
            <Key size={16} />
            {pt ? 'Chaves de API' : 'API Keys'}
          </SectionTitle>
          <SectionDesc>
            {pt
              ? 'Estas chaves são usadas pelo Prompt Lab e Image Gen. Cada serviço tem um plano gratuito.'
              : 'These keys are used by Prompt Lab and Image Gen. Each service has a free tier.'}
          </SectionDesc>

          {API_KEYS.map((def) => {
            const value = keys[def.id as keyof ApiKeys];
            const isVisible = visible[def.id] ?? false;
            return (
              <KeyRow key={def.id}>
                <KeyLabel>
                  {def.label}
                  <KeyBadge active={Boolean(value)}>
                    {value ? (pt ? 'ativa' : 'active') : (pt ? 'vazia' : 'empty')}
                  </KeyBadge>
                  <KeyHelp>— {def.help}</KeyHelp>
                </KeyLabel>
                <InputRow>
                  <InputWrap>
                    <Input
                      type={isVisible ? 'text' : 'password'}
                      value={value}
                      onChange={(e) => handleChange(def.id, e.target.value)}
                      placeholder={def.placeholder}
                      spellCheck={false}
                      autoComplete="off"
                    />
                    <ToggleVisBtn
                      onClick={() => setVisible((v) => ({ ...v, [def.id]: !isVisible }))}
                      title={isVisible ? 'Hide' : 'Show'}
                    >
                      {isVisible ? <EyeOff size={13} /> : <Eye size={13} />}
                    </ToggleVisBtn>
                  </InputWrap>
                  <IconBtn
                    danger
                    onClick={() => handleClear(def.id)}
                    title={pt ? 'Limpar' : 'Clear'}
                  >
                    <Trash2 size={13} />
                  </IconBtn>
                  <a href={def.linkUrl} target="_blank" rel="noopener noreferrer" style={{ textDecoration: 'none' }}>
                    <IconBtn title={def.linkLabel}>
                      <ExternalLink size={13} />
                    </IconBtn>
                  </a>
                </InputRow>
              </KeyRow>
            );
          })}

          <SaveBar>
            {saved ? <SavedMsg>{pt ? '✓ Guardado' : '✓ Saved'}</SavedMsg> : <span />}
            <SaveBtn onClick={handleSave} disabled={!dirty}>
              <Save size={13} />
              {pt ? 'Guardar' : 'Save'}
            </SaveBtn>
          </SaveBar>
        </Section>

        <SecurityNote>
          <Shield size={14} style={{ flexShrink: 0, marginTop: 2 }} />
          <span>
            {pt
              ? 'As chaves são enviadas diretamente do teu browser para o serviço de IA — nunca passam pelos nossos servidores. Podes removê-las a qualquer momento.'
              : 'Keys are sent directly from your browser to the AI provider — they never pass through our servers. You can remove them at any time.'}
          </span>
        </SecurityNote>
      </Container>
    </Page>
  );
}
