import { useState, useEffect } from 'react';
import styled from '@emotion/styled';
import { keyframes } from '@emotion/react';
import { theme } from '@atlantis/shared';

function pad2(n: number): string {
  return n.toString().padStart(2, '0');
}

function hourToText(h: number, m: number, locale: string): string {
  if (locale === 'pt') {
    const hStr = h === 1 ? '1 hora' : `${h} horas`;
    if (m === 0) return hStr;
    if (m === 15) return `${hStr} e um quarto`;
    if (m === 30) return `${hStr} e meia`;
    if (m === 45) return `um quarto para as ${h === 12 ? 1 : h + 1}`;
    return `${hStr} e ${m} minutos`;
  }
  const period = h < 12 ? 'AM' : 'PM';
  const h12 = h % 12 || 12;
  if (m === 0) return `${h12} o'clock ${period}`;
  if (m === 15) return `quarter past ${h12} ${period}`;
  if (m === 30) return `half past ${h12} ${period}`;
  if (m === 45) return `quarter to ${(h12 % 12) + 1} ${period}`;
  return `${h12}:${pad2(m)} ${period}`;
}

function AnalogClock({ hours, minutes, seconds }: { hours: number; minutes: number; seconds: number }) {
  const size = 140;
  const cx = size / 2;
  const cy = size / 2;
  const r = 60;

  const toRad = (deg: number) => (deg * Math.PI) / 180;
  const secondAngle = (seconds / 60) * 360 - 90;
  const minuteAngle = (minutes / 60) * 360 + (seconds / 60) * 6 - 90;
  const hourAngle = ((hours % 12) / 12) * 360 + (minutes / 60) * 30 - 90;

  const secX = cx + (r - 16) * Math.cos(toRad(secondAngle));
  const secY = cy + (r - 16) * Math.sin(toRad(secondAngle));
  const minX = cx + (r - 14) * Math.cos(toRad(minuteAngle));
  const minY = cy + (r - 14) * Math.sin(toRad(minuteAngle));
  const hrX = cx + (r - 28) * Math.cos(toRad(hourAngle));
  const hrY = cy + (r - 28) * Math.sin(toRad(hourAngle));

  return (
    <svg viewBox={`0 0 ${size} ${size}`} width={size} height={size}>
      <circle cx={cx} cy={cy} r={r} fill={theme.colors.surface} stroke={theme.colors.border} strokeWidth={1.5} />

      {Array.from({ length: 12 }, (_, i) => {
        const n = i + 1;
        const angle = (n / 12) * 360 - 90;
        const nx = cx + (r - 12) * Math.cos(toRad(angle));
        const ny = cy + (r - 12) * Math.sin(toRad(angle));
        return (
          <text key={n} x={nx} y={ny + 3} fill={theme.colors.mainText} fontSize={10} fontWeight={600} textAnchor="middle" fontFamily={theme.typography.fontFamily}>
            {n}
          </text>
        );
      })}

      {Array.from({ length: 60 }, (_, i) => {
        const angle = (i / 60) * 360 - 90;
        const isHour = i % 5 === 0;
        const outerR = r - 1;
        const innerR = isHour ? r - 7 : r - 4;
        return (
          <line
            key={i}
            x1={cx + innerR * Math.cos(toRad(angle))}
            y1={cy + innerR * Math.sin(toRad(angle))}
            x2={cx + outerR * Math.cos(toRad(angle))}
            y2={cy + outerR * Math.sin(toRad(angle))}
            stroke={isHour ? theme.colors.mainTextMuted : theme.colors.border}
            strokeWidth={isHour ? 1.5 : 0.8}
          />
        );
      })}

      <line x1={cx} y1={cy} x2={hrX} y2={hrY} stroke={theme.colors.mainText} strokeWidth={3} strokeLinecap="round" />
      <line x1={cx} y1={cy} x2={minX} y2={minY} stroke={theme.colors.accent} strokeWidth={2} strokeLinecap="round" />
      <line
        x1={cx - 8 * Math.cos(toRad(secondAngle))}
        y1={cy - 8 * Math.sin(toRad(secondAngle))}
        x2={secX} y2={secY}
        stroke="#f87171" strokeWidth={1} strokeLinecap="round"
      />

      <circle cx={cx} cy={cy} r={3} fill={theme.colors.accent} />
      <circle cx={cx} cy={cy} r={1.5} fill="#f87171" />
    </svg>
  );
}

const fadeIn = keyframes`
  from { opacity: 0; transform: translateY(4px); }
  to { opacity: 1; transform: translateY(0); }
`;

const Wrapper = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  height: 100%;
  animation: ${fadeIn} 0.3s ease both;
`;

const Header = styled.div`
  font-size: 11px;
  font-weight: 600;
  font-family: ${theme.typography.fontFamilyMono};
  color: ${theme.colors.mainTextMuted};
  letter-spacing: 0.06em;
  text-transform: uppercase;
  margin-bottom: 6px;
  align-self: flex-start;
`;

const ClockArea = styled.div`
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 6px;
`;

const Digital = styled.div`
  font-family: ${theme.typography.fontFamilyMono};
  font-size: 22px;
  font-weight: 700;
  color: ${theme.colors.mainText};
  letter-spacing: 0.04em;
`;

const TimeText = styled.div`
  font-family: ${theme.typography.fontFamily};
  font-size: 11px;
  color: ${theme.colors.mainTextMuted};
  text-align: center;
`;

const DateLine = styled.div`
  font-family: ${theme.typography.fontFamilyMono};
  font-size: 11px;
  color: ${theme.colors.mainTextMuted};
  letter-spacing: 0.04em;
  text-transform: uppercase;
  margin-top: 2px;
`;

const TzLine = styled.div`
  font-family: ${theme.typography.fontFamilyMono};
  font-size: 10px;
  color: ${theme.colors.mainTextMuted};
  opacity: 0.6;
  letter-spacing: 0.04em;
`;

interface AnalogClockWidgetProps {
  locale: string;
}

export function AnalogClockWidget({ locale }: AnalogClockWidgetProps) {
  const [hours, setHours] = useState(() => new Date().getHours());
  const [minutes, setMinutes] = useState(() => new Date().getMinutes());
  const [seconds, setSeconds] = useState(() => new Date().getSeconds());

  useEffect(() => {
    const tick = () => {
      const now = new Date();
      setHours(now.getHours());
      setMinutes(now.getMinutes());
      setSeconds(now.getSeconds());
    };
    const id = setInterval(tick, 1000);
    return () => clearInterval(id);
  }, []);

  const h12 = hours % 12 || 12;
  const now = new Date();
  const dateStr = now.toLocaleDateString(locale === 'pt' ? 'pt-PT' : 'en-GB', {
    weekday: 'long',
    day: 'numeric',
    month: 'long',
  });
  const tz = Intl.DateTimeFormat().resolvedOptions().timeZone;

  return (
    <Wrapper>
      <Header>{locale === 'pt' ? 'Relogio' : 'Clock'}</Header>
      <ClockArea>
        <AnalogClock hours={hours} minutes={minutes} seconds={seconds} />
        <Digital>
          {pad2(hours)}:{pad2(minutes)}
          <span style={{ fontSize: '14px', opacity: 0.5 }}>:{pad2(seconds)}</span>
        </Digital>
        <TimeText>{hourToText(h12, minutes, locale)}</TimeText>
        <DateLine>{dateStr}</DateLine>
        <TzLine>{tz}</TzLine>
      </ClockArea>
    </Wrapper>
  );
}
